def render_svg_icon(name: str, extra_classes: str = "", size: int = 20) -> str:
    path = _SVG_PATHS.get(name.strip())
    if not path:
        # Fallback circle dot
        return f'<svg class="{extra_classes}" width="{size}" height="{size}" viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="12" r="5"/></svg>'
    return (
        f'<svg class="{extra_classes} inline-block align-middle" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="currentColor" style="display: inline-block;">'
        f'<path d="{path}"/></svg>'
    )


def replace_material_icons_with_svg(html: str) -> str:
    """Replace all <span class="material-symbols-...">name</span> with inline SVGs."""
    def _repl(match: re.Match) -> str:
        tag_attrs = match.group(1)
        icon_name = match.group(2).strip()
        # Parse size from text-[Npx] if present
        size = 20
        sz_m = re.search(r'text-\[(\d+)px\]', tag_attrs)
        if sz_m:
            size = int(sz_m.group(1))
        # Keep classes but remove material-symbols-outlined
        cls_match = re.search(r'class="([^"]*)"', tag_attrs)
        classes = cls_match.group(1) if cls_match else ""
        classes = classes.replace("material-symbols-outlined", "").strip()
        return render_svg_icon(icon_name, extra_classes=classes, size=size)

    pattern = re.compile(r'<span([^>]*material-symbols[^>]*)>\s*([a-zA-Z0-9_-]+)\s*</span>')
    return pattern.sub(_repl, html)
